import type { DrawerProps } from "./drawer.types";

import React, { forwardRef, useState, useCallback, useRef } from "react";
import { clsx } from "clsx";
import * as RadixDialog from "@radix-ui/react-dialog";
import { Slot } from "@radix-ui/react-slot";
import { Close as CloseIcon } from "@exp-textura/icons";
import { IconButton } from "@components/icon-button";

import { DrawerClasses } from "./drawer.styles";
import { DrawerContext, useDrawerContext } from "./hooks/use-drawer-context";
import { DrawerOverlay } from "./drawer.overlay";
import { DrawerPush } from "./drawer.push";

const DrawerRoot = forwardRef<HTMLDivElement, DrawerProps>(
  (
    {
      children,
      onOpenChange,
      dismissible = true,
      open: openProp,
      defaultOpen = false,
      layoutMode = "overlay",
      modal = false,
      ...props
    },
    ref,
  ) => {
    const [internalOpen, setInternalOpen] = useState(defaultOpen);
    const triggerRef = useRef<HTMLButtonElement>(null);

    const isControlled = openProp !== undefined;
    const open = isControlled ? openProp : internalOpen;

    const handleOpenChange = useCallback(
      (nextOpen: boolean) => {
        if (!isControlled) {
          setInternalOpen(nextOpen);
        }
        onOpenChange?.(nextOpen);
      },
      [isControlled, onOpenChange],
    );

    const { trigger, content, closeIconButton } = getValidDrawerChildren(children);

    const contextValue = React.useMemo(
      () => ({
        open,
        onOpenChange: handleOpenChange,
        layoutMode,
        modal: layoutMode === "push" ? false : modal,
        dismissible,
        triggerRef,
      }),
      [open, handleOpenChange, layoutMode, modal, dismissible],
    );

    const Implementation = layoutMode === "push" ? DrawerPush : DrawerOverlay;

    return (
      <DrawerContext.Provider value={contextValue}>
        <Implementation
          ref={ref}
          drawerClose={closeIconButton}
          drawerContent={content}
          drawerTrigger={trigger}
          {...props}
        />
      </DrawerContext.Provider>
    );
  },
);

DrawerRoot.displayName = "Drawer";

const Title = ({
  children,
  asChild,
  ...props
}: React.ComponentPropsWithoutRef<typeof RadixDialog.Title> & { asChild?: boolean }) => {
  const { layoutMode } = useDrawerContext();

  if (layoutMode === "overlay") {
    return (
      <RadixDialog.Title
        asChild={asChild}
        className={DrawerClasses.title}
        data-drawer-type="title"
        {...props}
      >
        {children}
      </RadixDialog.Title>
    );
  }

  const Comp = asChild ? Slot : "h2";

  // In push mode, we render a semantic heading directly (or the child)
  return (
    <Comp className={DrawerClasses.title} data-drawer-type="title" {...props}>
      {children}
    </Comp>
  );
};
Title.displayName = "Drawer.Title";

const Trigger = ({
  children,
  ...props
}: React.ComponentPropsWithoutRef<typeof RadixDialog.Trigger>) => {
  const { layoutMode, onOpenChange, triggerRef } = useDrawerContext();

  if (layoutMode === "overlay") {
    return (
      <RadixDialog.Trigger data-drawer-type="trigger" {...props} asChild>
        {children}
      </RadixDialog.Trigger>
    );
  }

  return (
    <Slot
      ref={triggerRef}
      data-drawer-type="trigger"
      onClick={() => onOpenChange?.(true)}
      {...props}
    >
      {children}
    </Slot>
  );
};
Trigger.displayName = "Drawer.Trigger";

const Close = ({
  children,
  ...props
}: React.ComponentPropsWithoutRef<typeof RadixDialog.Close>) => {
  const { layoutMode, onOpenChange } = useDrawerContext();

  if (layoutMode === "overlay") {
    return (
      <RadixDialog.Close data-drawer-type="close" {...props} asChild>
        {children}
      </RadixDialog.Close>
    );
  }

  return (
    <Slot data-drawer-type="close" onClick={() => onOpenChange?.(false)} {...props}>
      {children}
    </Slot>
  );
};
Close.displayName = "Drawer.Close";

const CloseIconButton = ({
  children,
  className,
  "aria-label": customAriaLabel,
  ...props
}: React.ComponentPropsWithoutRef<typeof IconButton>) => {
  const { layoutMode, onOpenChange } = useDrawerContext();
  const buttonClasses = clsx(DrawerClasses.closeIconButton, className);
  const commonProps = {
    "aria-label": customAriaLabel || "Close drawer",
  } as const;

  if (layoutMode === "overlay") {
    return (
      <RadixDialog.Close asChild data-drawer-type="close-button">
        <IconButton buttonType="secondary" className={buttonClasses} {...commonProps} {...props}>
          {children ? children : <CloseIcon />}
        </IconButton>
      </RadixDialog.Close>
    );
  }

  return (
    <IconButton
      buttonType="secondary"
      className={buttonClasses}
      data-drawer-type="close-button"
      onClick={() => onOpenChange?.(false)}
      {...commonProps}
      {...props}
    >
      {children ? children : <CloseIcon />}
    </IconButton>
  );
};
CloseIconButton.displayName = "Drawer.CloseIconButton";

const Content = ({ children, tabIndex = 0, ...props }: React.ComponentPropsWithoutRef<"div">) => (
  <div className={DrawerClasses.content} data-drawer-type="content" tabIndex={tabIndex} {...props}>
    {children}
  </div>
);
Content.displayName = "Drawer.Content";

const Footer = ({ children, ...props }: React.ComponentPropsWithoutRef<"footer">) => (
  <footer className={DrawerClasses.footer} data-drawer-type="footer" {...props}>
    {children}
  </footer>
);
Footer.displayName = "Drawer.Footer";

type DrawerComponent = typeof DrawerRoot & {
  Trigger: typeof Trigger;
  Close: typeof Close;
  CloseIconButton: typeof CloseIconButton;
  Title: typeof Title;
  Content: typeof Content;
  Footer: typeof Footer;
};
const Drawer = DrawerRoot as DrawerComponent;

Drawer.Trigger = Trigger;
Drawer.Close = Close;
Drawer.CloseIconButton = CloseIconButton;
Drawer.Title = Title;
Drawer.Content = Content;
Drawer.Footer = Footer;

export default Drawer;

const getValidDrawerChildren = (
  children: React.ReactNode,
): {
  trigger: React.ReactNode[];
  content: React.ReactNode[];
  closeIconButton: React.ReactNode[];
} => {
  let titleCount = 0;
  let closeIconButtonCount = 0;
  let triggerCount = 0;
  let contentCount = 0;
  let footerCount = 0;

  const trigger: React.ReactNode[] = [];
  const content: React.ReactNode[] = [];
  const closeIconButton: React.ReactNode[] = [];

  React.Children.forEach(children, (child) => {
    if (React.isValidElement(child)) {
      const displayName = (child.type as { displayName?: string }).displayName;

      if (displayName !== "Drawer.Trigger" && displayName !== "Drawer.CloseIconButton") {
        content.push(child);
      }

      if (displayName === "Drawer.Content") {
        contentCount++;
      } else if (displayName === "Drawer.Footer") {
        footerCount++;
      } else if (displayName === "Drawer.Title") {
        titleCount++;
      } else if (displayName === "Drawer.Trigger") {
        trigger.push(child);
        triggerCount++;
      } else if (displayName === "Drawer.CloseIconButton") {
        closeIconButton.push(child);
        closeIconButtonCount++;
      } else {
        throw new Error(
          "<Drawer> only accepts <Drawer.Title>, <Drawer.CloseIconButton>, <Drawer.Trigger>, <Drawer.Content>, and <Drawer.Footer> as children.",
        );
      }
    }
  });

  if (contentCount > 1)
    throw new Error(`<Drawer> can only have one <Drawer.Content>. Found ${contentCount}.`);
  if (closeIconButtonCount > 1)
    throw new Error(
      `<Drawer> can only have one <Drawer.CloseIconButton>. Found ${closeIconButtonCount}.`,
    );
  if (footerCount > 1)
    throw new Error(`<Drawer> can only have one <Drawer.Footer>. Found ${footerCount}.`);
  if (titleCount > 1)
    throw new Error(`<Drawer> can only have one <Drawer.Title>. Found ${titleCount}.`);
  if (triggerCount > 1)
    throw new Error(`<Drawer> can only have one <Drawer.Trigger>. Found ${triggerCount}.`);

  return { trigger, content, closeIconButton };
};
